package com.chx.claims.claim.application;
import com.chx.claims.claim.domain.Claim; import com.chx.claims.claim.infra.ClaimRepository; import com.chx.claims.common.error.ResourceNotFoundException; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ClaimQueryService { private final ClaimRepository repo; public ClaimQueryService(ClaimRepository r){repo=r;} @Transactional(readOnly=true) public List<Claim> mine(UUID claimant){var result=repo.findByClaimantId(claimant); result.forEach(this::initialize); return result;} @Transactional(readOnly=true) public Claim get(UUID id,UUID caller){Claim c=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Claim not found")); if(!c.getClaimantId().equals(caller))throw new ResourceNotFoundException("Claim not found"); initialize(c); return c;} private void initialize(Claim c){c.getStatusHistory().size();c.getInfoRequests().size();} }
